<?php use VazinCMS\Security; ?><section class="title"><div><h1>سرویس‌ها</h1><p>مدیریت سرویس، انقضا و تنظیمات تمدید مشتریان</p></div><a class="button secondary" href="/admin/renewals">صف تمدیدها</a></section><section class="services-list"><?php foreach($services as $s):?><article class="panel service-card"><div><h2><?=Security::e($s['name'])?></h2><p><?=Security::e($s['customer'].' — '.$s['email'])?></p></div><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="id" value="<?=$s['id']?>"><div class="grid service-fields"><label>وضعیت<select name="status"><?php foreach(['pending'=>'در انتظار','active'=>'فعال','suspended'=>'تعلیق','cancelled'=>'لغو','expired'=>'منقضی'] as $v=>$l):?><option value="<?=$v?>" <?=$s['status']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>شناسه سرویس<input name="identifier" value="<?=Security::e((string)$s['identifier'])?>"></label><label>تاریخ انقضا<input type="datetime-local" name="expires_at" value="<?=Security::e($s['expires_at']?date('Y-m-d\TH:i',strtotime($s['expires_at'])):'')?>"></label><label>دوره تمدید<select name="billing_cycle"><?php foreach(['monthly'=>'ماهانه','quarterly'=>'سه‌ماهه','yearly'=>'سالانه'] as $v=>$l):?><option value="<?=$v?>" <?=$s['billing_cycle']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>مبلغ تمدید<input type="number" min="0" step="0.01" name="renewal_price" value="<?=Security::e((string)$s['renewal_price'])?>"></label><label>ارز<input name="currency" maxlength="8" value="<?=Security::e((string)$s['currency'])?>"></label></div><label class="check"><input type="checkbox" name="auto_renew" value="1" <?=$s['auto_renew']?'checked':''?>> تمدید خودکار فعال باشد</label><label>یادداشت<textarea name="notes" rows="2"><?=Security::e((string)$s['notes'])?></textarea></label><button>ذخیره سرویس</button></form></article><?php endforeach;?></section>
